const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fmt = (n) => (typeof n === 'number' && Number.isFinite(n)) ? n.toLocaleString('en-US', { maximumFractionDigits: 2 }) : esc(n);
const layout = (title, body) => `<div style="font-family:Segoe UI,Helvetica,Arial,sans-serif;max-width:600px;margin:0 auto;color:#0f172a">
  <div style="background:#4f46e5;color:#fff;padding:20px 24px;border-radius:12px 12px 0 0"><b style="font-size:18px">VizIntel Dashboard</b></div>
  <div style="border:1px solid #e2e8f0;border-top:0;padding:24px;border-radius:0 0 12px 12px">
    <h2 style="margin:0 0 12px;font-size:20px">${title}</h2>${body}
  </div>
  <p style="color:#94a3b8;font-size:12px;text-align:center;margin-top:12px">Automated message from the VizIntel n8n workflows.</p>
</div>`;
const button = (href, label) => `<p style="margin:20px 0 0"><a href="${esc(href)}" style="background:#4f46e5;color:#fff;padding:10px 18px;border-radius:8px;text-decoration:none">${esc(label)}</a></p>`;

const data = $input.first().json;
const period = new Date(data.period.from).toDateString() + ' - ' + new Date(data.period.to).toDateString();
const stat = (label, value) => `<td style="padding:12px;background:#f8fafc;border-radius:8px;text-align:center">
  <div style="font-size:22px;font-weight:700">${fmt(value)}</div><div style="color:#64748b;font-size:12px">${label}</div></td>`;

return (data.reports || []).map((r) => {
  const recent = (r.recentDatasets || []).map((d) => `<li>${esc(d.name)} <span style="color:#64748b">(${fmt(d.rows)} rows)</span></li>`).join('');
  const searches = (r.topSearches || []).map((s) => `<code style="background:#eef2ff;padding:2px 6px;border-radius:4px">${esc(s.term)}</code>`).join(' ');
  const body = `<p>Hi ${esc(r.user.name)}, here is your activity for <b>${esc(period)}</b>.</p>
    <table style="width:100%;border-spacing:8px"><tr>
      ${stat('Datasets uploaded', r.datasetsUploaded)}${stat('Rows processed', r.rowsProcessed)}${stat('Page views', r.activity.pageViews)}${stat('Searches', r.activity.searches)}
    </tr></table>
    ${recent ? '<p style="margin-bottom:4px"><b>Recent uploads</b></p><ul style="margin-top:4px">' + recent + '</ul>' : ''}
    ${searches ? '<p><b>Top searches:</b> ' + searches + '</p>' : ''}
    ${button(r.dashboardUrl, 'Open your dashboard')}`;
  return { json: { to: r.user.email, subject: 'Your VizIntel weekly report (' + period + ')', html: layout('Weekly analytics report', body) } };
});

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fmt = (n) => (typeof n === 'number' && Number.isFinite(n)) ? n.toLocaleString('en-US', { maximumFractionDigits: 2 }) : esc(n);
const layout = (title, body) => `<div style="font-family:Segoe UI,Helvetica,Arial,sans-serif;max-width:600px;margin:0 auto;color:#0f172a">
  <div style="background:#4f46e5;color:#fff;padding:20px 24px;border-radius:12px 12px 0 0"><b style="font-size:18px">VizIntel Dashboard</b></div>
  <div style="border:1px solid #e2e8f0;border-top:0;padding:24px;border-radius:0 0 12px 12px">
    <h2 style="margin:0 0 12px;font-size:20px">${title}</h2>${body}
  </div>
  <p style="color:#94a3b8;font-size:12px;text-align:center;margin-top:12px">Automated message from the VizIntel n8n workflows.</p>
</div>`;
const button = (href, label) => `<p style="margin:20px 0 0"><a href="${esc(href)}" style="background:#4f46e5;color:#fff;padding:10px 18px;border-radius:8px;text-decoration:none">${esc(label)}</a></p>`;

const data = $input.first().json;
const t = data.totals;
const top = (data.reports || []).slice(0, 10).map((r) => `<tr><td style="padding:4px 8px">${esc(r.user.name)}</td>
  <td style="padding:4px 8px;text-align:right">${fmt(r.datasetsUploaded)}</td><td style="padding:4px 8px;text-align:right">${fmt(r.activity.pageViews)}</td></tr>`).join('');
const body = `<p>Platform totals for the last ${data.period.days} days:</p>
  <ul><li><b>${fmt(t.users)}</b> active users</li><li><b>${fmt(t.datasetsUploaded)}</b> datasets / <b>${fmt(t.rowsProcessed)}</b> rows</li>
  <li><b>${fmt(t.pageViews)}</b> page views, <b>${fmt(t.clicks)}</b> clicks, <b>${fmt(t.searches)}</b> searches</li></ul>
  ${top ? '<table style="font-size:14px"><tr><th style="text-align:left;padding:4px 8px">User</th><th style="padding:4px 8px">Uploads</th><th style="padding:4px 8px">Page views</th></tr>' + top + '</table>' : ''}`;
return [{ json: { to: $env.VIZINTEL_ADMIN_EMAIL || '', subject: 'VizIntel platform digest', html: layout('Weekly platform digest', body) } }];
